package com.example.shortener.api;

import static org.assertj.core.api.Assertions.assertThat;

import java.time.Instant;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;

import com.fasterxml.jackson.databind.JsonNode;
import com.example.shortener.domain.ClickEventRepository;
import com.example.shortener.service.ApiException;
import com.example.shortener.service.ClickRecorder;
import com.example.shortener.service.LinkService;
import com.example.shortener.support.IntegrationTest;
import org.junit.jupiter.api.Test;
import org.springframework.http.HttpStatus;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.transaction.support.TransactionTemplate;

/**
 * TC-FR3-03: a click being recorded and the link being deleted at the same moment. Each test
 * forces one interleaving by holding the first operation's transaction open (and so its row lock)
 * while the second starts; either way no click may survive the deletion. The expiry-change tests
 * do the same for an expiry change against click recording and against deletion.
 */
class ClickDeletionRaceTest extends IntegrationTest {

    @Autowired
    private ClickRecorder recorder;

    @Autowired
    private LinkService links;

    @Autowired
    private ClickEventRepository clicks;

    @Autowired
    private TransactionTemplate tx;

    @Test
    void TC_FR3_03_clickInFlightWhenDeleteArrivesIsErasedByTheDelete() throws Exception {
        JsonNode link = create("https://example.com/race-1");
        String code = link.get("code").asText();
        Long id = repository.findByCode(code).orElseThrow().getId();
        CountDownLatch recordingHoldsLock = new CountDownLatch(1);

        CompletableFuture<Void> recording = CompletableFuture.runAsync(() -> tx.executeWithoutResult(s -> {
            recorder.record(id);            // joins this transaction: takes the row lock, inserts
            recordingHoldsLock.countDown();
            sleep(300);                     // keep the lock while the delete starts
        }));
        assertThat(recordingHoldsLock.await(5, TimeUnit.SECONDS)).isTrue();
        CompletableFuture<Void> deleting = CompletableFuture.runAsync(
                () -> links.delete(code, link.get("managementToken").asText()));

        CompletableFuture.allOf(recording, deleting).get(10, TimeUnit.SECONDS);
        assertThat(repository.findByCode(code).orElseThrow().isDeleted()).isTrue();
        assertThat(clicks.countByLinkId(id)).as("the delete waited for the click, then erased it").isZero();
    }

    @Test
    void TC_FR3_03_clickArrivingDuringDeleteIsNotRecordedAfterIt() throws Exception {
        JsonNode link = create("https://example.com/race-2");
        String code = link.get("code").asText();
        Long id = repository.findByCode(code).orElseThrow().getId();
        CountDownLatch deleteHoldsLock = new CountDownLatch(1);

        CompletableFuture<Void> deleting = CompletableFuture.runAsync(() -> tx.executeWithoutResult(s -> {
            links.delete(code, link.get("managementToken").asText());  // takes the row lock, erases, tombstones
            deleteHoldsLock.countDown();
            sleep(300);                                                // commit only after the click starts
        }));
        assertThat(deleteHoldsLock.await(5, TimeUnit.SECONDS)).isTrue();
        CompletableFuture<Void> recording = CompletableFuture.runAsync(() -> recorder.record(id));

        CompletableFuture.allOf(recording, deleting).get(10, TimeUnit.SECONDS);
        assertThat(clicks.countByLinkId(id)).as("the click waited, then saw the tombstone and recorded nothing").isZero();
    }

    // --- expiry changes on the same row lock --------------------------------------------------

    private static final Instant NEW_EXPIRY = Instant.parse("2031-01-01T00:00:00Z");

    @Test
    void TC_FR3_02_expiryChangeWaitsForAClickInFlightAndBothPersist() throws Exception {
        JsonNode link = create("https://example.com/race-expiry-1", null, "2030-01-01T00:01:00Z");
        String code = link.get("code").asText();
        Long id = repository.findByCode(code).orElseThrow().getId();
        CountDownLatch recordingHoldsLock = new CountDownLatch(1);

        CompletableFuture<Void> recording = CompletableFuture.runAsync(() -> tx.executeWithoutResult(s -> {
            recorder.record(id);
            recordingHoldsLock.countDown();
            sleep(300);
        }));
        assertThat(recordingHoldsLock.await(5, TimeUnit.SECONDS)).isTrue();
        CompletableFuture<Void> updating = CompletableFuture.runAsync(
                () -> links.updateExpiry(code, link.get("managementToken").asText(), NEW_EXPIRY));

        CompletableFuture.allOf(recording, updating).get(10, TimeUnit.SECONDS);
        assertThat(repository.findByCode(code).orElseThrow().getExpiresAt()).isEqualTo(NEW_EXPIRY);
        assertThat(clicks.countByLinkId(id)).isEqualTo(1);
    }

    @Test
    void TC_FR3_02_redirectDuringAnExpiryChangeIsServedAndItsClickIsRecorded() throws Exception {
        JsonNode link = create("https://example.com/race-expiry-2", null, "2030-01-01T00:01:00Z");
        String code = link.get("code").asText();
        Long id = repository.findByCode(code).orElseThrow().getId();
        CountDownLatch updateHoldsLock = new CountDownLatch(1);

        CompletableFuture<Void> updating = CompletableFuture.runAsync(() -> tx.executeWithoutResult(s -> {
            links.updateExpiry(code, link.get("managementToken").asText(), NEW_EXPIRY);
            updateHoldsLock.countDown();
            sleep(300);
        }));
        assertThat(updateHoldsLock.await(5, TimeUnit.SECONDS)).isTrue();
        int redirect = mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get("/" + code))
                .andReturn().getResponse().getStatus();

        updating.get(10, TimeUnit.SECONDS);
        assertThat(redirect).as("the redirect is served while the update holds the row lock").isEqualTo(302);
        assertThat(clicks.countByLinkId(id)).as("its click waited for the lock, then was recorded").isEqualTo(1);
        assertThat(repository.findByCode(code).orElseThrow().getExpiresAt()).isEqualTo(NEW_EXPIRY);
    }

    @Test
    void TC_FR3_03_expiryChangeArrivingDuringDeleteFindsTheTombstone() throws Exception {
        JsonNode link = create("https://example.com/race-expiry-3", null, "2030-01-01T00:01:00Z");
        String code = link.get("code").asText();
        String token = link.get("managementToken").asText();
        CountDownLatch deleteHoldsLock = new CountDownLatch(1);

        CompletableFuture<Void> deleting = CompletableFuture.runAsync(() -> tx.executeWithoutResult(s -> {
            links.delete(code, token);
            deleteHoldsLock.countDown();
            sleep(300);
        }));
        assertThat(deleteHoldsLock.await(5, TimeUnit.SECONDS)).isTrue();
        CompletableFuture<Object> updating = CompletableFuture.supplyAsync(() -> {
            try {
                return links.updateExpiry(code, token, NEW_EXPIRY);
            } catch (ApiException e) {
                return e.getStatus();
            }
        });

        deleting.get(10, TimeUnit.SECONDS);
        assertThat(updating.get(10, TimeUnit.SECONDS)).as("the update waited, then saw the tombstone")
                .isEqualTo(HttpStatus.NOT_FOUND);
        assertThat(repository.findByCode(code).orElseThrow().isDeleted()).isTrue();
    }

    @Test
    void TC_FR3_03_deleteArrivingDuringAnExpiryChangeStillDeletes() throws Exception {
        JsonNode link = create("https://example.com/race-expiry-4", null, "2030-01-01T00:01:00Z");
        String code = link.get("code").asText();
        String token = link.get("managementToken").asText();
        CountDownLatch updateHoldsLock = new CountDownLatch(1);

        CompletableFuture<Void> updating = CompletableFuture.runAsync(() -> tx.executeWithoutResult(s -> {
            links.updateExpiry(code, token, NEW_EXPIRY);
            updateHoldsLock.countDown();
            sleep(300);
        }));
        assertThat(updateHoldsLock.await(5, TimeUnit.SECONDS)).isTrue();
        CompletableFuture<Void> deleting = CompletableFuture.runAsync(() -> links.delete(code, token));

        CompletableFuture.allOf(updating, deleting).get(10, TimeUnit.SECONDS);
        assertThat(repository.findByCode(code).orElseThrow().isDeleted()).as("the delete waited, then won").isTrue();
    }

    private static void sleep(long millis) {
        try {
            Thread.sleep(millis);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}

package com.example.shortener.api;

import static org.assertj.core.api.Assertions.assertThat;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.patch;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.header;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import java.time.Instant;
import java.util.List;
import java.util.Map;

import com.fasterxml.jackson.databind.JsonNode;
import com.example.shortener.support.IntegrationTest;
import com.example.shortener.support.MutableClock;
import org.junit.jupiter.api.Test;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.ResultActions;
import org.yaml.snakeyaml.Yaml;

/**
 * PATCH /api/links/{code}: the owner sets or removes a link's expiry. The clock starts at
 * {@link MutableClock#START} (2030-01-01T00:00:00Z) in every test.
 */
class LinkExpiryUpdateTest extends IntegrationTest {

    private static final String TOKEN = "X-Management-Token";
    private static final String IN_ONE_MINUTE = "2030-01-01T00:01:00Z";

    // --- FR1 set, remove, required field ---------------------------------------------------------

    @Test
    void TC_FR1_01_ownerSetsAFutureExpiryAndGetsUpdatedMetadata() throws Exception {
        JsonNode link = create("https://example.com/tc-fr1-01", null, IN_ONE_MINUTE);
        String code = link.get("code").asText();
        update(code, token(link), "{\"expiresAt\":\"2031-06-01T12:00:00Z\"}")
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.code").value(code))
                .andExpect(jsonPath("$.originalUrl").value("https://example.com/tc-fr1-01"))
                .andExpect(jsonPath("$.expiresAt").value("2031-06-01T12:00:00Z"))
                .andExpect(jsonPath("$.managementToken").doesNotExist());
        assertThat(storedExpiry(code)).isEqualTo(Instant.parse("2031-06-01T12:00:00Z"));
    }

    @Test
    void TC_FR1_02_explicitNullRemovesTheExpiry() throws Exception {
        JsonNode link = create("https://example.com/tc-fr1-02", null, IN_ONE_MINUTE);
        String code = link.get("code").asText();
        update(code, token(link), "{\"expiresAt\":null}")
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.expiresAt").doesNotExist()); // metadata omits an absent expiry, as before
        assertThat(storedExpiry(code)).isNull();
    }

    @Test
    void TC_FR1_03_omittedExpiresAtIsRejectedAndChangesNothing() throws Exception {
        JsonNode link = create("https://example.com/tc-fr1-03", null, IN_ONE_MINUTE);
        String code = link.get("code").asText();
        for (String body : List.of("{}", "{\"expires\":null}")) {
            update(code, token(link), body)
                    .andExpect(status().isBadRequest())
                    .andExpect(jsonPath("$.error").value("invalid_request"));
        }
        assertThat(storedExpiry(code)).as("an incomplete request never clears the expiry")
                .isEqualTo(Instant.parse(IN_ONE_MINUTE));
    }

    @Test
    void TC_FR1_04_malformedBodiesAndValuesAreRejectedAndChangeNothing() throws Exception {
        JsonNode link = create("https://example.com/tc-fr1-04", null, IN_ONE_MINUTE);
        String code = link.get("code").asText();
        for (String body : List.of("{not json", "[]", "null", "{\"expiresAt\":\"tomorrow\"}",
                "{\"expiresAt\":\"2031-13-45T00:00:00Z\"}", "{\"expiresAt\":{}}")) {
            update(code, token(link), body)
                    .andExpect(status().isBadRequest())
                    .andExpect(jsonPath("$.error").value("invalid_request"));
        }
        assertThat(storedExpiry(code)).isEqualTo(Instant.parse(IN_ONE_MINUTE));
    }

    // --- FR2 only the token holder ------------------------------------------------------------------

    @Test
    void TC_FR2_01_missingTokenIs401AndChangesNothing() throws Exception {
        String code = create("https://example.com/tc-fr2-01", null, IN_ONE_MINUTE).get("code").asText();
        update(code, null, "{\"expiresAt\":null}")
                .andExpect(status().isUnauthorized())
                .andExpect(jsonPath("$.error").value("missing_token"));
        assertThat(storedExpiry(code)).isEqualTo(Instant.parse(IN_ONE_MINUTE));
    }

    @Test
    void TC_FR2_02_wrongTokenIs403AndChangesNothing() throws Exception {
        JsonNode other = create("https://example.com/tc-fr2-02-other");
        String code = create("https://example.com/tc-fr2-02", null, IN_ONE_MINUTE).get("code").asText();
        update(code, token(other), "{\"expiresAt\":null}") // another link's valid token is still wrong here
                .andExpect(status().isForbidden())
                .andExpect(jsonPath("$.error").value("invalid_token"));
        assertThat(storedExpiry(code)).isEqualTo(Instant.parse(IN_ONE_MINUTE));
    }

    // --- FR3 immediate effect ------------------------------------------------------------------------

    @Test
    void TC_FR3_01_redirectsUseTheNewExpiryImmediately() throws Exception {
        JsonNode shortened = create("https://example.com/tc-fr3-01-a", null, IN_ONE_MINUTE);
        String a = shortened.get("code").asText();
        update(a, token(shortened), "{\"expiresAt\":\"2030-01-01T00:00:30Z\"}").andExpect(status().isOk());
        mvc.perform(get("/api/links/" + a)).andExpect(jsonPath("$.expiresAt").value("2030-01-01T00:00:30Z"));

        JsonNode removed = create("https://example.com/tc-fr3-01-b", null, "2030-01-01T00:00:10Z");
        String b = removed.get("code").asText();
        update(b, token(removed), "{\"expiresAt\":null}").andExpect(status().isOk());

        clock.advance(Duration.ofSeconds(31));
        mvc.perform(get("/" + a)).andExpect(status().isGone()).andExpect(jsonPath("$.error").value("expired"));
        mvc.perform(get("/" + b)).andExpect(status().isFound())
                .andExpect(header().string("Location", "https://example.com/tc-fr3-01-b"));
    }

    // --- FR4 an expired link is never revived ------------------------------------------------------

    @Test
    void TC_FR4_01_anExpiredLinkCannotBeExtendedOrClearedAndStaysExpired() throws Exception {
        JsonNode link = create("https://example.com/tc-fr4-01", null, "2030-01-01T00:00:10Z");
        String code = link.get("code").asText();
        clock.advance(Duration.ofSeconds(10)); // exactly at the expiry instant: expired (FR2 boundary of creation)
        for (String body : List.of("{\"expiresAt\":\"2031-01-01T00:00:00Z\"}", "{\"expiresAt\":null}")) {
            update(code, token(link), body)
                    .andExpect(status().isGone())
                    .andExpect(jsonPath("$.error").value("expired"));
        }
        assertThat(storedExpiry(code)).isEqualTo(Instant.parse("2030-01-01T00:00:10Z"));
        mvc.perform(get("/" + code)).andExpect(status().isGone());
    }

    @Test
    void TC_FR4_01_theTokenIsCheckedBeforeExpiryIsRevealed() throws Exception {
        String code = create("https://example.com/tc-fr4-01-token", null, "2030-01-01T00:00:10Z").get("code").asText();
        clock.advance(Duration.ofSeconds(11));
        update(code, "wrong", "{\"expiresAt\":null}").andExpect(status().isForbidden());
    }

    // --- FR5 past or present values ------------------------------------------------------------------

    @Test
    void TC_FR5_01_anExpiryAtOrBeforeNowIsRejectedAndChangesNothing() throws Exception {
        JsonNode link = create("https://example.com/tc-fr5-01", null, IN_ONE_MINUTE);
        String code = link.get("code").asText();
        for (String value : List.of("2030-01-01T00:00:00Z", "2029-12-31T23:59:59Z", "2030-01-01T00:00:00.0000009Z")) {
            update(code, token(link), "{\"expiresAt\":\"" + value + "\"}")
                    .andExpect(status().isBadRequest())
                    .andExpect(jsonPath("$.error").value("invalid_expiry"));
        }
        assertThat(storedExpiry(code)).isEqualTo(Instant.parse(IN_ONE_MINUTE));
    }

    // --- FR6 deleted and unknown links -----------------------------------------------------------------

    @Test
    void TC_FR6_01_deletedAndUnknownLinksAre404AndTheTombstoneStays() throws Exception {
        JsonNode link = create("https://example.com/tc-fr6-01");
        String code = link.get("code").asText();
        mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.delete("/api/links/" + code)
                .header(TOKEN, token(link))).andExpect(status().isNoContent());
        update(code, token(link), "{\"expiresAt\":\"2031-01-01T00:00:00Z\"}")
                .andExpect(status().isNotFound())
                .andExpect(jsonPath("$.error").value("not_found"));
        update("Zz9Zz9Zz", token(link), "{\"expiresAt\":null}").andExpect(status().isNotFound());
        assertThat(repository.findByCode(code).orElseThrow().isDeleted()).isTrue();
        assertThat(storedExpiry(code)).isNull();
    }

    // --- FR7 no maximum ---------------------------------------------------------------------------------

    @Test
    void TC_FR7_01_aFarFutureExpiryIsAcceptedAtStoredPrecision() throws Exception {
        JsonNode link = create("https://example.com/tc-fr7-01");
        String code = link.get("code").asText();
        update(code, token(link), "{\"expiresAt\":\"9999-12-31T23:59:59.999999Z\"}")
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.expiresAt").value("9999-12-31T23:59:59.999999Z"));
        assertThat(storedExpiry(code)).isEqualTo(Instant.parse("9999-12-31T23:59:59.999999Z"));
    }

    // --- NFR2 the API definition describes the operation -------------------------------------------------

    @Test
    @SuppressWarnings("unchecked")
    void TC_NFR2_01_theApiDefinitionDescribesTheExpiryChange() throws Exception {
        Map<String, Object> spec = new Yaml().load(Files.readString(Path.of("openapi.yaml")));
        assertThat((String) spec.get("openapi")).startsWith("3.");
        Map<String, Object> operation = (Map<String, Object>) ((Map<String, Object>) ((Map<String, Object>)
                spec.get("paths")).get("/api/links/{code}")).get("patch");
        assertThat(operation).as("PATCH /api/links/{code} is documented").isNotNull();
        assertThat(((Map<String, Object>) operation.get("responses")).keySet())
                .contains("200", "400", "401", "403", "404", "410", "429");

        Map<String, Object> components = (Map<String, Object>) spec.get("components");
        Map<String, Object> scheme = (Map<String, Object>) ((Map<String, Object>) components.get("securitySchemes"))
                .get("ManagementToken");
        assertThat(scheme).containsEntry("in", "header").containsEntry("name", TOKEN);
        assertThat(operation.get("security")).isEqualTo(List.of(Map.of("ManagementToken", List.of())));

        Map<String, Object> body = (Map<String, Object>) ((Map<String, Object>) components.get("schemas"))
                .get("UpdateLinkExpiryRequest");
        assertThat((List<String>) body.get("required")).containsExactly("expiresAt");
        assertThat(((Map<String, Object>) ((Map<String, Object>) body.get("properties")).get("expiresAt")))
                .containsEntry("nullable", true).containsEntry("format", "date-time");
    }

    private ResultActions update(String code, String token, String body) throws Exception {
        var request = patch("/api/links/" + code).contentType(MediaType.APPLICATION_JSON).content(body);
        return mvc.perform(token == null ? request : request.header(TOKEN, token));
    }

    private static String token(JsonNode created) {
        return created.get("managementToken").asText();
    }

    private Instant storedExpiry(String code) {
        return repository.findByCode(code).orElseThrow().getExpiresAt();
    }
}

package com.example.shortener.api;

import static com.example.shortener.api.ErrorContractAndHeadersTest.peer;
import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatCode;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.delete;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.patch;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.header;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import java.time.Duration;
import java.util.concurrent.atomic.AtomicInteger;

import com.fasterxml.jackson.databind.JsonNode;
import com.example.shortener.config.ShortenerProperties;
import com.example.shortener.service.ManagementTokenRateLimiter;
import com.example.shortener.service.RateLimitedException;
import com.example.shortener.support.IntegrationTest;
import com.example.shortener.support.MutableClock;
import org.junit.jupiter.api.Test;
import org.springframework.http.MediaType;

/**
 * FR10: at most 10 wrong management tokens per client IP per rolling minute, shared by stats, delete
 * and expiry changes.
 */
class ManagementTokenRateLimitTest extends IntegrationTest {

    private static final AtomicInteger NEXT = new AtomicInteger(1);

    // --- unit: the rolling window --------------------------------------------------------------

    @Test
    void TC_FR10_01_tenWrongTokensAreAdmittedTheEleventhIsLimitedUntilTheWindowRolls() {
        MutableClock time = new MutableClock();
        ManagementTokenRateLimiter limiter = new ManagementTokenRateLimiter(
                new ShortenerProperties("./data", new ShortenerProperties.RateLimit(20, 10), 8, 16_384), time);
        for (int i = 0; i < 10; i++) {
            time.advance(Duration.ofSeconds(1));
            limiter.recordFailure("192.0.2.1"); // attempts at t = 1 .. 10 s
        }
        assertThatThrownBy(() -> limiter.recordFailure("192.0.2.1"))
                .isInstanceOfSatisfying(RateLimitedException.class, e -> {
                    assertThat(e.getError()).isEqualTo("rate_limited");
                    assertThat(e.getRetryAfterSeconds()).isEqualTo(51L); // until the t=1s attempt leaves the window
                });
        assertThatCode(() -> limiter.recordFailure("192.0.2.2")).as("another peer is unaffected").doesNotThrowAnyException();

        time.advance(Duration.ofSeconds(61)); // every attempt (including the rejected ones) has left the window
        assertThatCode(() -> limiter.recordFailure("192.0.2.1")).doesNotThrowAnyException();
    }

    // --- integration: through stats and delete --------------------------------------------------

    @Test
    void TC_FR10_02_wrongTokensAcrossStatsAndDeleteShareOneLimit() throws Exception {
        JsonNode link = create("https://example.com/limit");
        String code = link.get("code").asText();
        String ip = freshIp();
        for (int i = 0; i < 10; i++) {
            var request = i % 2 == 0 ? get("/api/links/" + code + "/stats") : delete("/api/links/" + code);
            mvc.perform(request.header("X-Management-Token", "wrong").with(peer(ip)))
                    .andExpect(status().isForbidden()).andExpect(jsonPath("$.error").value("invalid_token"));
        }
        mvc.perform(delete("/api/links/" + code).header("X-Management-Token", "wrong").with(peer(ip)))
                .andExpect(status().isTooManyRequests())
                .andExpect(jsonPath("$.error").value("rate_limited"))
                .andExpect(header().exists("Retry-After"));
        mvc.perform(get("/api/links/" + code + "/stats").header("X-Management-Token", "wrong").with(peer(ip)))
                .andExpect(status().isTooManyRequests());
        assertThat(repository.findByCode(code).orElseThrow().isDeleted()).isFalse();
    }

    @Test
    void TC_FR2_03_wrongTokensOnExpiryChangesCountTowardTheSameLimit() throws Exception {
        JsonNode link = create("https://example.com/limit-patch", null, "2030-01-01T00:01:00Z");
        String code = link.get("code").asText();
        String ip = freshIp();
        for (int i = 0; i < 10; i++) {
            var request = i % 2 == 0 ? expiryChange(code) : get("/api/links/" + code + "/stats");
            mvc.perform(request.header("X-Management-Token", "wrong").with(peer(ip)))
                    .andExpect(status().isForbidden()).andExpect(jsonPath("$.error").value("invalid_token"));
        }
        mvc.perform(expiryChange(code).header("X-Management-Token", "wrong").with(peer(ip)))
                .andExpect(status().isTooManyRequests())
                .andExpect(jsonPath("$.error").value("rate_limited"))
                .andExpect(header().exists("Retry-After"));
        mvc.perform(delete("/api/links/" + code).header("X-Management-Token", "wrong").with(peer(ip)))
                .andExpect(status().isTooManyRequests()); // the PATCH failures counted for delete too
        assertThat(repository.findByCode(code).orElseThrow().getExpiresAt()).isNotNull();

        mvc.perform(expiryChange(code).header("X-Management-Token", link.get("managementToken").asText()).with(peer(ip)))
                .andExpect(status().isOk()); // the real owner is never locked out
        assertThat(repository.findByCode(code).orElseThrow().getExpiresAt()).isNull();
    }

    @Test
    void TC_FR10_02_missingTokensNeverCount() throws Exception {
        String code = create("https://example.com/missing").get("code").asText();
        String ip = freshIp();
        for (int i = 0; i < 25; i++) {
            mvc.perform(get("/api/links/" + code + "/stats").with(peer(ip)))
                    .andExpect(status().isUnauthorized()).andExpect(jsonPath("$.error").value("missing_token"));
        }
        mvc.perform(get("/api/links/" + code + "/stats").header("X-Management-Token", "wrong").with(peer(ip)))
                .andExpect(status().isForbidden());
    }

    @Test
    void TC_FR10_02_validTokenStillWorksWhileTheIpIsLimitedAndForwardedForIsIgnored() throws Exception {
        JsonNode link = create("https://example.com/owner");
        String code = link.get("code").asText();
        String ip = freshIp();
        for (int i = 0; i < 11; i++) {
            mvc.perform(get("/api/links/" + code + "/stats").header("X-Management-Token", "wrong").with(peer(ip)));
        }
        mvc.perform(get("/api/links/" + code + "/stats").header("X-Management-Token", "wrong").with(peer(ip))
                        .header("X-Forwarded-For", "203.0.113.200"))
                .andExpect(status().isTooManyRequests()); // a spoofed header does not escape the limit
        mvc.perform(get("/api/links/" + code + "/stats").header("X-Management-Token", link.get("managementToken").asText())
                        .with(peer(ip)))
                .andExpect(status().isOk()); // the real owner is never locked out
    }

    private static org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder expiryChange(String code) {
        return patch("/api/links/" + code).contentType(MediaType.APPLICATION_JSON).content("{\"expiresAt\":null}");
    }

    private static String freshIp() {
        return "198.18.200." + NEXT.getAndIncrement();
    }
